/* Offline interaction study. Every record and receipt is synthetic. No fetch, storage or product API. */
'use strict';
const main = document.querySelector('#main');
const concepts = ['dispatch','ensemble','deliveries'];
const requested = new URLSearchParams(location.search).get('concept');
const concept = concepts.includes(requested) ? requested : 'dispatch';
document.documentElement.dataset.concept = concept;
document.querySelector(`.research-bar nav [data-concept="${concept}"]`).setAttribute('aria-current','page');
document.title = `Relay ${concept[0].toUpperCase()+concept.slice(1)} · Design prototype`;
const tasks = [
  {id:'release',project:'Relay website',title:'Make the release notes easier to read',short:'Release notes',summary:'Turn the latest changes into a clear, accessible release page. Keep existing links and make the mobile layout comfortable to read.',owner:'Mira',role:'Builder',file:'web/release/ReleaseNotes.tsx',status:'Awaiting decision',state:'pending',time:'4 min ago',result:'A clearer release page',handoff:'The layout is ready. Review the proposed file change before the sample task continues.'},
  {id:'research',project:'Customer research',title:'Find the themes in interview notes',short:'Interview synthesis',summary:'Read the six sample interviews and group recurring requests. Every finding should link to the observation that supports it.',owner:'Nico',role:'Researcher',file:'research/interview-summary.md',status:'Ready to review',state:'done',time:'18 min ago',result:'What people need next',handoff:'Three themes have supporting excerpts. Review the sample synthesis and ask a follow-up.'},
  {id:'docs',project:'Developer guide',title:'Check the setup guide on a clean workspace',short:'Setup guide',summary:'Check the sample installation steps, identify missing context and prepare a concise set of corrections for review.',owner:'Iris',role:'Reviewer',file:'docs/getting-started.md',status:'Checking',state:'active',time:'Just now',result:'A smoother first run',handoff:'The sample reviewer is comparing the written steps with the recorded check. No real command is running.'}
];
const agents = [{id:'lead',name:'Relay',role:'Lead',initials:'R',state:'Coordinating',description:'Keeps the objective, scope and next handoff together.'},{id:'researcher',name:'Nico',role:'Researcher',initials:'N',state:'Research complete',description:'Found the essential changes and traced them to source notes.'},{id:'builder',name:'Mira',role:'Builder',initials:'M',state:'Needs your decision',description:'Prepared the proposed release page and its change summary.'},{id:'reviewer',name:'Iris',role:'Reviewer',initials:'I',state:'Review ready',description:'Checked the sample change for mobile reading and keyboard access.'}];
let selected = 'release', selectedAgent = 'builder', view = 'brief', mobileDetail = false;
const decisions = {}, messages = {}, drafts = {};
let renderedTask = null;
const esc = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({check:'<path d="m5 12 4 4 10-10"/>',arrow:'<path d="m9 5-7 7 7 7M3 12h18"/>',file:'<path d="M14 2H5v20h14V7zM14 2v5h5M8 12h8M8 16h6"/>',message:'<path d="M21 15a3 3 0 0 1-3 3H8l-5 4V5a3 3 0 0 1 3-3h12a3 3 0 0 1 3 3z"/>',plus:'<path d="M12 5v14M5 12h14"/>',stop:'<rect x="5" y="5" width="14" height="14" rx="2"/>'})[name]||''}</svg>`;
const brand = subtitle => `<div class="brand"><span class="brand-symbol" aria-hidden="true"><i></i><i></i><i></i></span>relay${subtitle?`<small>${subtitle}</small>`:''}</div>`;
const task = () => tasks.find(item => item.id===selected);
const status = item => decisions[item.id] ? (decisions[item.id]==='approve' ? 'Approved in preview' : 'Denied in preview') : item.status;
const state = item => decisions[item.id] ? 'done' : item.state;
const tag = item => `<span class="tag ${state(item)}">${status(item)}</span>`;
const avatar = name => `<span class="avatar" aria-hidden="true">${esc(name[0])}</span>`;
const context = item => `<div class="context"><span>${esc(item.project)}</span><span class="divider"></span><span>Sample workspace</span><span class="divider"></span>${tag(item)}</div>`;
const tabs = () => `<nav class="tabs" aria-label="Task content">${[['brief','Overview'],['chat','Conversation'],['evidence','Evidence']].map(([id,label])=>`<button data-view="${id}" aria-pressed="${view===id}">${label}</button>`).join('')}</nav>`;
function decision(item){
  if(decisions[item.id]) return `<section class="decision resolved" aria-label="Preview decision result"><div class="context">Simulation recorded</div><h2 class="small-heading">${decisions[item.id]==='approve'?'Approved for this preview':'Denied for this preview'}</h2><p>${decisions[item.id]==='approve'?'The sample agent can continue in this prototype.':'The sample agent will keep the proposed change unapplied.'} No real files, permissions or tasks changed.</p><button class="reset-link" data-reset="${item.id}">Reset this decision</button></section>`;
  if(item.id!=='release') return `<section class="decision"><div class="context">${item.id==='research'?'Result ready':'Work in progress'}</div><h2 class="small-heading">${item.id==='research'?'Review the supporting observations':'A check is still in progress'}</h2><p>${esc(item.handoff)}</p><div class="decision-actions"><button data-view="evidence">Inspect sample evidence</button><button data-view="chat">Ask ${esc(item.owner)}</button></div></section>`;
  return `<section class="decision" aria-label="Simulated approval"><div class="context">One decision for you</div><h2 class="small-heading">Allow the proposed file change?</h2><p>Mira wants to update <code>${esc(item.file)}</code> in the sample managed workspace.</p><p>No source publication. No network access.</p><div class="decision-actions"><button class="primary" data-decision="approve">Approve preview</button><button data-decision="deny">Deny preview</button><small>Simulation only</small></div></section>`;
}
function brief(item){return `<div class="brief-columns"><section><h2 class="small-heading">What happens next</h2><ul class="steps"><li>${icon('check')}<span>Understand the objective</span></li><li>${icon('check')}<span>Prepare a reviewable result</span></li><li>${icon(item.id==='release'?'file':'check')}<span>${item.id==='release'?'Your decision on the proposed change':'Review the supporting evidence'}</span></li></ul></section><section><h2 class="small-heading">Responsible agent</h2><div class="person-line">${avatar(item.owner)}<div><strong>${esc(item.owner)}</strong><small>${esc(item.role)} · sample assignment</small></div></div><p class="muted">${esc(item.handoff)}</p></section></div>`;}
function evidence(item){return `<section aria-label="Sample evidence"><h2 class="small-heading">Evidence you can inspect</h2>${[{name:item.id==='release'?'Change prepared':'Source material read',body:item.file,time:'10:42'},{name:item.id==='release'?'Type check passed in sample':'References attached in sample',body:'Illustrative receipt · not a command run or verified product result',time:'10:43'},{name:'Review boundary',body:'Managed sample workspace only. Publication is a separate decision.',time:'10:44'}].map(r=>`<div class="receipt">${icon('check')}<div><strong>${esc(r.name)}</strong><p>${esc(r.body)}</p></div><span class="receipt-time">${r.time}</span></div>`).join('')}<p class="evidence-note">These receipts demonstrate presentation only. Real Relay evidence must come from persisted tool and verification records.</p></section>`;}
function chat(item){const name=concept==='ensemble'?agents.find(a=>a.id===selectedAgent).name:item.owner;return `<section aria-label="Sample conversation"><div class="chat-line">${avatar('You')}<div><strong>You</strong><small>Sample brief</small><p>${esc(item.summary)}</p></div></div><div class="chat-line">${avatar(name)}<div><strong>${esc(name)}</strong><small>Sample response</small><p>${esc(item.handoff)}</p></div></div>${(messages[item.id]||[]).map(message=>`<div class="chat-line">${avatar('You')}<div><strong>You</strong><small>Preview message</small><p>${esc(message)}</p></div></div><div class="chat-line">${avatar(name)}<div><strong>${esc(name)}</strong><small>Simulated reply</small><p>Your note is attached to this sample task. This offline prototype does not call a model.</p></div></div>`).join('')}<form class="chat-form"><label for="message">Message ${esc(name)}</label><textarea id="message" name="message" placeholder="Try a follow-up about this task" required></textarea><div class="form-end"><small>Preview only. Messages stay in this page until reload.</small><button class="primary" type="submit">Send preview</button></div></form></section>`;}
const content = item => `<div class="view-content">${view==='chat'?chat(item):view==='evidence'?evidence(item):brief(item)}</div>`;
function dispatch(){const item=task();return `<div class="dispatch ${mobileDetail?'is-detail':''}"><header class="dispatch-header">${brand('Dispatch')}<div class="header-right"><span class="context">Personal workspace</span><button class="minor-button" data-view="chat">${icon('message')}<span>Open conversation</span></button>${avatar('You')}</div></header><section class="dispatch-top"><div><h1>Your work, moving forward.</h1><p>A decision to make. A result to review. A task in motion.</p></div><button class="primary" data-new>${icon('plus')} New objective</button></section><div class="dispatch-body"><section class="dispatch-queue" aria-label="Task inbox"><div class="queue-filter"><strong>Attention & activity</strong><span class="count">3 sample tasks</span></div>${tasks.map(t=>`<button class="queue-item" data-task="${t.id}" aria-pressed="${t.id===selected}"><span class="row-head"><span class="project">${esc(t.project)}</span>${tag(t)}</span><strong class="row-title">${esc(t.title)}</strong><span class="row-foot"><span>${esc(t.owner)} · ${esc(t.role)}</span><span>${t.time}</span></span></button>`).join('')}<p class="queue-bottom"><strong>Nothing slips away.</strong><br>Decisions stay with the task and its evidence.</p></section><article class="dispatch-detail"><button class="back" data-back>${icon('arrow')} All work</button>${context(item)}<h1 class="task-heading">${esc(item.title)}</h1><p class="task-summary">${esc(item.summary)}</p>${decision(item)}${tabs()}${content(item)}</article></div></div>`;}
function agentNode(agent){return `<button class="agent-node" data-agent="${agent.id}" aria-pressed="${selectedAgent===agent.id}">${avatar(agent.name)}<span><strong class="agent-name">${agent.name}</strong><p>${agent.role}</p><span class="node-state">${agent.id==='builder'&&decisions.release?status(tasks[0]):agent.state}</span></span></button>`;}
function ensemble(){const item=task(),agent=agents.find(a=>a.id===selectedAgent);return `<div class="ensemble"><header class="ensemble-header">${brand('Ensemble')}<nav class="ensemble-projects" aria-label="Team objectives">${tasks.map(t=>`<button data-task="${t.id}" aria-pressed="${selected===t.id}">${t.short}</button>`).join('')}</nav></header><section class="team-stage" aria-label="Sample agent team"><div class="stage-intro"><div><h1>A small team. One shared objective.</h1><p>Follow the handoff, open an assignment, shape what happens next.</p></div><span class="stage-pill">Illustrative team relationships</span></div><div class="team-map"><div class="team-lead">${agentNode(agents[0])}</div><div class="team-agents">${agents.slice(1).map(agentNode).join('')}</div></div></section><div class="ensemble-work"><article class="assignment"><div class="context"><strong>${esc(agent.name)}'s assignment</strong><span class="divider"></span>${tag(item)}</div><h2 class="task-heading">${esc(item.title)}</h2><p class="task-summary">${esc(agent.description)}</p>${decision(item)}${tabs()}${content(item)}</article><aside class="handoffs"><h2 class="small-heading">How the work connects</h2><div class="handoff"><strong>Relay → Nico</strong><p>Find the changes that matter and their source material.</p><small>Brief passed · sample</small></div><div class="handoff"><strong>Nico → Mira</strong><p>Three priorities, source notes and a clear mobile reading goal.</p><small>Research returned · sample</small></div><div class="handoff"><strong>Mira → Iris</strong><p>A proposed file change, ready for independent review.</p><small>Review requested · sample</small></div><p class="team-explanation">Agent relationships are synthetic. The drawing does not establish real concurrency, delegation or granted access.</p></aside></div></div>`;}
function artifact(item){if(item.id==='release')return `<div class="artifact-preview" aria-label="Sample proposed diff"><div class="file-heading"><span>ReleaseNotes.tsx</span><span>Illustrative diff</span></div><div class="diff-lines" tabindex="0" role="region" aria-label="Scrollable sample diff"><div class="diff-line"><span>18</span> &lt;section aria-label="Release notes"&gt;</div><div class="diff-line remove"><span>19</span>−  &lt;div className="changes-grid"&gt;</div><div class="diff-line add"><span>19</span>+  &lt;ol className="release-timeline"&gt;</div><div class="diff-line add"><span>20</span>+    &lt;ReleaseChange title="A clearer start" /&gt;</div><div class="diff-line add"><span>21</span>+    &lt;ReleaseChange title="Review with confidence" /&gt;</div><div class="diff-line add"><span>22</span>+  &lt;/ol&gt;</div><div class="diff-line"><span>23</span> &lt;/section&gt;</div></div></div><p class="artifact-notes">The proposed structure replaces competing columns with a reading sequence. Links keep their existing destinations. The sample change has not been applied.</p>`;return `<div class="artifact-preview"><div class="file-heading"><span>${esc(item.file)}</span><span>Sample document</span></div><div style="padding:24px"><h2 class="small-heading">${item.id==='research'?'Clarity before more controls':'Make the first success obvious'}</h2><p style="margin-top:14px">${item.id==='research'?'The sample interviews describe a need to understand the current task, see why it paused, and find the next useful action.':'The sample guide should show prerequisites first, then one complete successful path, with recovery steps beside the point of failure.'}</p><p class="muted" style="margin-top:14px">Illustrative content for comparing the three interface directions.</p></div></div>`;}
function deliveries(){const item=task();return `<div class="deliveries"><header class="deliveries-header">${brand('Deliveries')}<p>Good work deserves<br>a clear review.</p><button class="minor-button" data-new>${icon('plus')} New objective</button></header><nav class="delivery-shelf" aria-label="Sample deliveries">${tasks.map(t=>`<button class="delivery-card" data-task="${t.id}" aria-pressed="${selected===t.id}"><span class="card-label"><span>${t.project}</span><span>${t.owner}</span></span><strong class="delivery-title">${t.result}</strong>${tag(t)}</button>`).join('')}</nav><div class="delivery-layout"><article class="artifact-document"><div class="artifact-caption"><span>Prepared by ${item.owner} · ${item.role}</span><span>Sample delivery</span></div><p class="document-subtitle">${esc(item.project)}</p><h1 class="document-heading">${esc(item.result)}</h1><p class="task-summary">${esc(item.summary)}</p>${view==='brief'?artifact(item):''}${tabs()}${content(item)}</article><aside class="delivery-review"><nav class="itinerary" aria-label="Review itinerary"><h2 class="small-heading">Your review</h2>${[['brief','Read the proposed result','1'],['evidence','Inspect supporting checks','2'],['chat','Discuss with the agent','3']].map(([id,label,num])=>`<button data-view="${id}" aria-pressed="${view===id}"><span>${label}</span><span>${num}</span></button>`).join('')}</nav>${decision(item)}<div class="person-line">${avatar(item.owner)}<div><strong>${item.owner} prepared this</strong><small>${item.role} · sample workspace</small></div></div><button class="reset-link" data-reset-all>Reset prototype decisions</button></aside></div></div>`;}
function render(){const previous=main.querySelector('#message');if(previous&&renderedTask)drafts[renderedTask]=previous.value;main.innerHTML=concept==='ensemble'?ensemble():concept==='deliveries'?deliveries():dispatch();renderedTask=selected;const next=main.querySelector('#message');if(next)next.value=drafts[selected]||'';}
let toastTimer;
function announce(message){clearTimeout(toastTimer);document.querySelector('#announcement').textContent=message;toastTimer=setTimeout(()=>document.querySelector('#announcement').textContent='',5000);}
main.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;
  if(button.dataset.task){selected=button.dataset.task;view='brief';mobileDetail=true;render();if(innerWidth<=760){main.querySelector('.dispatch-detail .back')?.focus();}}
  else if(button.dataset.agent){selectedAgent=button.dataset.agent;view='brief';render();main.querySelector(`[data-agent="${selectedAgent}"]`)?.focus();}
  else if(button.dataset.view){view=button.dataset.view;mobileDetail=true;render();main.querySelector(`.tabs [data-view="${view}"]`)?.focus();if(concept==='deliveries'&&innerWidth<=760)main.querySelector('.artifact-document')?.scrollIntoView({block:'start'});}
  else if(button.dataset.decision){decisions[selected]=button.dataset.decision;render();main.querySelector('.decision .reset-link')?.focus();announce(`${button.dataset.decision==='approve'?'Approval':'Denial'} recorded in preview only. No real action occurred.`);}
  else if(button.dataset.reset){delete decisions[button.dataset.reset];render();main.querySelector('[data-decision=approve]')?.focus();announce('Sample decision reset.');}
  else if(button.hasAttribute('data-reset-all')){Object.keys(decisions).forEach(key=>delete decisions[key]);render();announce('All preview decisions reset.');}
  else if(button.hasAttribute('data-back')){mobileDetail=false;render();main.querySelector(`[data-task="${selected}"]`)?.focus();}
  else if(button.hasAttribute('data-new')){selected='release';view='chat';mobileDetail=true;render();main.querySelector('#message')?.focus();announce('Try a new objective as a preview message. No real task will start.');}
});
main.addEventListener('submit',event=>{if(!event.target.matches('.chat-form'))return;event.preventDefault();const input=event.target.querySelector('textarea'),message=input.value.trim();if(!message)return;(messages[selected]??=[]).push(message);input.value='';render();main.querySelector('#message')?.focus();announce('Preview message added. The reply is simulated.');});
document.querySelector('#theme').addEventListener('click',()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';const theme=document.querySelector('#theme');theme.textContent=dark?'Light theme':'Dark theme';theme.setAttribute('aria-label',`Switch to ${dark?'light':'dark'} theme`);});
render();
